import BookingsActive from "../assets/bottomTabIcons/BookingTabIconActive.svg";
import JobsActive from "../assets/bottomTabIcons/JobsTabIconActive.svg";
import ProfileActive from "../assets/bottomTabIcons/ProfileTabIconActive.svg";
import JobsStackNavigator from "./JobsStackNavigator";

export default function BottomTabNavigator() {
  const [activeTab, setActiveTab] = useState("Bookings");

  const _renderIconText = ({ text, focused }) => (
    <Text
      style={[
        styles.label,
        {
          color: focused ? "#7638A9" : "#C6C6C6",
          backgroundColor: "transparent",
        },
      ]}
    >
      {text}
    </Text>
  );

  const _renderIcon = (routeName, focused) => {
    let IconComponent;

    switch (routeName) {
      case "Book workers":
        IconComponent = PlusIconTab;
        break;
      case "Bookings":
        IconComponent = focused ? BookingsActive : BookingsIconTab;
        break;
      case "Jobs":
        IconComponent = focused ? JobsActive : JobsIconTab;
        break;
      case "Profile":
        IconComponent = focused ? ProfileActive : ProfileIconTab;
        break;
      default:
        return null;
    }

    return (
      <View style={styles.iconContainer}>
        {IconComponent && <IconComponent width={40} height={25} />}
        {_renderIconText({ text: routeName, focused })}
      </View>
    );
  };

  const renderTabBar = ({ routeName, focused, navigate }) => (
    <TouchableOpacity
      onPress={() => {
        if (activeTab !== routeName) {
          setActiveTab(routeName);
          navigate(routeName);
        }
      }}
      style={styles.tabbarItem}
    >
      {_renderIcon(routeName, routeName === activeTab)}
    </TouchableOpacity>
  );

  return (
    <CurvedBottomBarExpo.Navigator
      type="DOWN"
      style={styles.bottomBar}
      height={Platform.OS === "ios" ? 80 : 75}
      circleWidth={60}
      bgColor="#F9F9F9"
      initialRouteName="Bookings"
      circlePosition="LEFT"
      borderTopLeftRight
      renderCircle={({ navigate }) => (
        <TouchableOpacity
          style={styles.btnCircleUp}
          onPress={() => navigate("Book workers")}
        >
          <PlusIconTab style={styles.imgCircle} />
        </TouchableOpacity>
      )}
      tabBar={({ routeName, focused, navigate }) =>
        renderTabBar({ routeName, focused, navigate })
      }
    >
      <CurvedBottomBarExpo.Screen
        name="Book workers"
        component={CreateBooking}
        options={screenOptions}
      />
      <CurvedBottomBarExpo.Screen
        name="Bookings"
        position="LEFT"
        component={Bookings}
        options={screenOptions}
      />
      <CurvedBottomBarExpo.Screen
        name="Jobs"
        position="LEFT"
        component={JobsStackNavigator}
        options={screenOptions}
      />
      <CurvedBottomBarExpo.Screen
        name="Profile"
        position="LEFT"
        component={ProfileStackNavigator}
        options={screenOptions}
      />
    </CurvedBottomBarExpo.Navigator>
  );
}

