import { useImageStore } from "../../store/useImageStore"; 


const CustomTabButton = ({ onPress }) => {
  const { showActionSheetWithOptions } = useActionSheet();
  const router = useRouter();

  const openSettings = () => {
    Alert.alert(
      "Permission Required",
      "Please enable permissions in settings to continue.",
      [
        { text: "Cancel", style: "cancel" },
        { text: "Open Settings", onPress: () => Linking.openSettings() },
      ]
    );
  };

  const openCamera = async () => {
    const { status } = await ImagePicker.requestCameraPermissionsAsync();

    if (status === "denied") {
      openSettings();
      return;
    }

    if (status === "granted") {
      const result = await ImagePicker.launchCameraAsync({
        allowsEditing: true,
        aspect: [2, 3],
        quality: 1,
      });

      if (!result.canceled) {
        useImageStore.getState().setImage(result.assets[0]); // Store image globally
        router.push("/(tabs)/create/add-details");
      }
    }
  };

  const openGallery = async () => {
    const { status } = await ImagePicker.requestMediaLibraryPermissionsAsync();

    if (status === "denied") {
      openSettings();
      return;
    }

    if (status === "granted") {
      const result = await ImagePicker.launchImageLibraryAsync({
        allowsEditing: true,
        aspect: [2, 3],
        quality: 1,
      });

      if (!result.canceled) {
        useImageStore.getState().setImage(result.assets[0]); // Store image globally
        router.push("/(tabs)/create/add-details");
      }
    }
  };

  const showActionSheet = () => {
    const options = ["Capture Photo", "Pick from Gallery", "Cancel"];
    const cancelButtonIndex = 2;

    showActionSheetWithOptions(
      {
        options,
        cancelButtonIndex,
        containerStyle: {
          backgroundColor: "#222", // Dark mode background
          borderTopLeftRadius: 25,
